const TOPIC_NAMES = {
  "1": "Fundamentos de informática y arquitectura de equipos",
  "2": "Sistemas operativos de puesto de usuario",
  "3": "Sistemas corporativos y servidores",
  "4": "Redes y conectividad",
  "5": "Internet, servicios y certificados",
  "6": "Soporte técnico y atención a usuarios",
  "7": "Seguridad informática",
  "8": "Bases de datos",
  "9": "Automatización, scripting y desarrollo web básico",
  "10": "Formatos de datos e intercambio de información",
  "11": "Fundamentos del desarrollo de software",
  "12": "Entornos de desarrollo y herramientas de trabajo",
  "13": "Virtualización, almacenamiento y copias de seguridad",
  "14": "Servicios cloud y herramientas colaborativas",
  "15": "Sistemas audiovisuales, multimedia y producción digital",
  "16": "Documentación, inventario y procedimientos",
  "17": "Protección de datos y uso responsable de sistemas",
  "18": "Derechos y obligaciones de los trabajadores en materia de prevención de riesgos laborales"
};

const CATEGORY_TOPICS = {
  Redes: [4, 5],
  Sistemas: [2, 3, 6, 7, 14, 16, 17, 18],
  Desarrollo: [8, 9, 10, 11, 12],
  Hardware: [1, 13, 15]
};

const ROUND_SECONDS = 30;
const ROUND_LENGTH = 10;
const EXAM_LENGTH = 40;
const TRIVIAL_TARGET = 3;
const STORAGE_KEY = "rtve-estudio-v1";
const QUIZ_MODES = ["practice", "daily", "kahoot", "exam"];

function shuffle(items) {
  const result = items.slice();
  for (let index = result.length - 1; index > 0; index -= 1) {
    const randomIndex = Math.floor(Math.random() * (index + 1));
    [result[index], result[randomIndex]] = [result[randomIndex], result[index]];
  }
  return result;
}

function calculateScore(correct, remaining, duration) {
  if (!correct || !Number.isFinite(remaining) || !Number.isFinite(duration) || duration <= 0) return 0;
  return 500 + Math.round(500 * Math.max(0, Math.min(remaining / duration, 1)));
}

function normalizeProgress(raw) {
  const input = raw && typeof raw === "object" ? raw : {};
  const validIds = new Set(QUESTION_BANK.map(question => question.id));
  const cleanIds = value => Array.isArray(value) ? [...new Set(value.filter(id => validIds.has(id)))] : [];
  const learned = cleanIds(input.learned);
  const learnedIds = new Set(learned);
  const review = cleanIds(input.review).filter(id => !learnedIds.has(id));
  const trivial = Object.fromEntries(Object.keys(CATEGORY_TOPICS).map(category => {
    const value = input.trivial?.[category];
    return [category, Number.isInteger(value) ? Math.max(0, Math.min(value, TRIVIAL_TARGET)) : 0];
  }));
  const bestScore = Number.isInteger(input.bestScore) ? Math.max(0, Math.min(input.bestScore, ROUND_LENGTH * 1000)) : 0;
  const temas = Object.fromEntries(Object.keys(TOPIC_NAMES).map(tema => {
    const value = input.temas?.[tema];
    return [tema, Number.isInteger(value) ? Math.max(0, Math.min(value, TRIVIAL_TARGET)) : 0];
  }));
  return { learned, review, trivial, temas, bestScore, study: Study.normalize(input.study, validIds) };
}

function readProgress() {
  const stored = localStorage.getItem(STORAGE_KEY);
  return normalizeProgress(stored ? JSON.parse(stored) : null);
}

async function persistProgress(change) {
  const save = () => {
    const latest = readProgress();
    change(latest);
    const saved = normalizeProgress(latest);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(saved));
    return saved;
  };
  return navigator.locks ? navigator.locks.request(STORAGE_KEY, save) : save();
}

function prepareQuestion(question) {
  return {
    ...question,
    choices: shuffle(question.options.map((text, index) => ({ text, correct: index === question.answer })))
  };
}

function filteredQuestions(temas) {
  const selected = new Set(temas);
  return QUESTION_BANK.filter(question => selected.has(question.tema));
}

function setFormattedText(element, text) {
  element.replaceChildren();
  String(text).split("`").forEach((part, index) => {
    if (index % 2 === 0) element.append(document.createTextNode(part));
    else {
      const code = document.createElement("code");
      code.textContent = part;
      element.append(code);
    }
  });
}

function questionMeta(question) {
  const origin = question.origin === "ADAPTADA"
    ? question.source.startsWith("L03")
      ? " · Adaptada de Ingeniería Superior Informática (otra ocupación)"
      : " · Adaptada de Técnica Informática"
    : " · Pregunta propia";
  return `Tema ${question.tema} · ${question.id}${origin}`;
}

function renderOptions(container, question, selected, resolved, disabled, onAnswer) {
  container.replaceChildren();
  question.choices.forEach((choice, index) => {
    const item = document.createElement("li");
    const button = document.createElement("button");
    button.type = "button";
    button.className = "answer-option";
    button.disabled = resolved || disabled;
    button.dataset.answer = String(index);
    button.setAttribute("aria-pressed", String(selected === index));
    const letter = document.createElement("span");
    letter.className = "option-letter";
    letter.textContent = "ABCD"[index];
    const content = document.createElement("span");
    content.className = "option-content";
    setFormattedText(content, choice.text);
    button.append(letter, content);
    if (resolved && (choice.correct || selected === index)) {
      const result = document.createElement("span");
      result.className = "option-result";
      result.textContent = choice.correct ? "✓ Correcta" : "× Tu elección";
      button.classList.add(choice.correct ? "is-correct" : "is-wrong");
      button.append(result);
    }
    button.addEventListener("click", () => onAnswer(index));
    item.append(button);
    container.append(item);
  });
}

function renderFeedback(element, title, question, selectedText) {
  element.replaceChildren();
  const heading = document.createElement("strong");
  heading.textContent = title;
  const answer = document.createElement("p");
  setFormattedText(answer, `Respuesta: ${question.options[question.answer]}`);
  const explanation = document.createElement("p");
  setFormattedText(explanation, question.explanation);
  element.append(heading);
  if (selectedText && selectedText !== question.options[question.answer]) {
    const selected = document.createElement("p");
    setFormattedText(selected, `Elegiste: ${selectedText}`);
    element.append(selected);
  }
  element.append(answer, explanation);
  element.hidden = false;
}

document.addEventListener("DOMContentLoaded", () => {
  const byId = id => document.getElementById(id);
  const state = { view: "home", mode: "practice", temas: Object.keys(TOPIC_NAMES).map(Number), boardPage: 0, reviewIndex: 0, scope: "all", quiz: null, trivial: null, flash: null };
  let timer = null;
  let deadline = 0;
  let progress;
  let pendingSave = Promise.resolve();
  let unsavedChanges = [];
  let storageAvailable = true;
  const trivialPools = {};

  function showStorageNotice() {
    storageAvailable = false;
    byId("storage-notice").hidden = false;
  }

  try {
    progress = readProgress();
  } catch {
    progress = normalizeProgress(null);
    showStorageNotice();
  }

  function saveProgress(change) {
    pendingSave = pendingSave.then(async () => {
      try {
        const changes = [...unsavedChanges, change];
        progress = await persistProgress(saved => { changes.forEach(apply => apply(saved)); });
        unsavedChanges = [];
        storageAvailable = true;
        byId("storage-notice").hidden = true;
      } catch {
        unsavedChanges.push(change);
        change(progress);
        showStorageNotice();
      }
      updateCounts();
    });
    return pendingSave;
  }

  function renderProgress() {
    const summary = Study.summary(QUESTION_BANK, progress.study);
    byId("progress-save-status").textContent = storageAvailable
      ? "El progreso se guarda en este navegador, también cuando estudias sin conexión."
      : "No se ha podido leer o guardar el progreso. Los cambios de esta sesión no están guardados; los datos anteriores no se han borrado.";
    byId("progress-best").textContent = `${progress.bestScore.toLocaleString("es-ES")} puntos`;
    byId("progress-learned").textContent = `${progress.learned.length} / ${QUESTION_BANK.length}`;
    byId("progress-review").textContent = String(progress.review.length);
    byId("progress-trivial").textContent = `${Object.values(progress.temas).filter(count => count === TRIVIAL_TARGET).length} / ${Object.keys(TOPIC_NAMES).length}`;
    byId("progress-tested").textContent = `${summary.tested} / ${summary.total}`;
    byId("progress-mastered").textContent = String(summary.consolidated);
    byId("progress-due").textContent = String(summary.due);
    const exams = byId("progress-exams");
    exams.replaceChildren();
    progress.study.exams.slice(-5).reverse().forEach(exam => {
      const item = document.createElement("li");
      const date = document.createElement("strong");
      date.textContent = new Date(`${exam.day}T12:00:00`).toLocaleDateString("es-ES");
      const result = document.createElement("span");
      result.textContent = `${exam.net.toLocaleString("es-ES", { maximumFractionDigits: 2 })} / ${exam.total} puntos netos · ${exam.correct} aciertos · ${exam.wrong} errores · ${exam.blank} en blanco`;
      item.append(date, result);
      exams.append(item);
    });
    if (!progress.study.exams.length) {
      const empty = document.createElement("li");
      empty.textContent = "Aún no has corregido ningún simulacro.";
      exams.append(empty);
    }
    const learned = new Set(progress.learned);
    const review = new Set(progress.review);
    const list = byId("progress-topics");
    list.replaceChildren();
    Object.entries(TOPIC_NAMES).forEach(([tema, title]) => {
      const questions = filteredQuestions([Number(tema)]);
      const item = document.createElement("li");
      const heading = document.createElement("h3");
      heading.textContent = `Tema ${tema.padStart(2, "0")} · ${title}`;
      const counts = document.createElement("p");
      const topic = summary.topics.find(item => item.topic === Number(tema));
      const consolidated = questions.filter(question => progress.study.cards[question.id]?.stage >= 3 && progress.study.cards[question.id]?.attempts > 0).length;
      counts.textContent = `${topic.tested} / ${questions.length} preguntas practicadas · ${consolidated} consolidadas · ${topic.accuracy === null ? "Sin respuestas evaluadas" : `${Math.round(topic.accuracy)} % de acierto`}`;
      const manual = document.createElement("p");
      manual.className = "muted";
      manual.textContent = `Tarjetas marcadas manualmente: ${questions.filter(question => learned.has(question.id)).length} aprendidas, ${questions.filter(question => review.has(question.id)).length} para repasar · Trivial: ${progress.temas[tema]} / ${TRIVIAL_TARGET}`;
      const bar = document.createElement("progress");
      bar.max = questions.length;
      bar.value = consolidated;
      bar.setAttribute("aria-label", `Preguntas consolidadas del tema ${tema}`);
      item.append(heading, counts, bar, manual);
      list.append(item);
    });
    const legacy = Object.entries(progress.trivial).filter(([, count]) => count > 0);
    byId("progress-legacy").hidden = legacy.length === 0;
    byId("progress-legacy").textContent = `Trivial de la versión anterior: ${legacy.map(([category, count]) => `${category}: ${count} / ${TRIVIAL_TARGET}`).join(" · ")}. Conservado por separado del progreso por tema.`;
  }

  function renderDashboard() {
    const summary = Study.summary(QUESTION_BANK, progress.study);
    byId("daily-count").textContent = `${Math.min(summary.today.answers, ROUND_LENGTH)} / ${ROUND_LENGTH}`;
    byId("daily-progress").value = Math.min(summary.today.answers, ROUND_LENGTH);
    byId("daily-message").textContent = summary.today.answers >= ROUND_LENGTH
      ? `Objetivo de hoy conseguido: ${summary.today.answers} preguntas distintas. Puedes seguir practicando; los repasos futuros mantienen su fecha.`
      : `Hoy llevas ${summary.today.answers} preguntas distintas. El plan prioriza tus repasos y combina temas. Repetir una pregunta no aumenta el objetivo ni los XP del día.`;
    byId("start-daily").firstChild.textContent = summary.today.answers >= ROUND_LENGTH ? "Seguir con 10 preguntas " : "Plan diario · 10 preguntas ";
    byId("due-total").textContent = String(summary.due);
    byId("tested-total").textContent = String(summary.tested);
    byId("mastered-total").textContent = String(summary.consolidated);
    byId("study-level").textContent = `Nivel ${summary.level}`;
    byId("study-xp").textContent = `${summary.xp} XP · ${100 - summary.levelProgress} para el siguiente nivel`;
    byId("study-streak").textContent = summary.streak >= 90 ? "90+" : String(summary.streak);
    byId("study-streak").setAttribute("aria-label", `${summary.streak >= 90 ? "Al menos " : ""}${summary.streak} ${summary.streak === 1 ? "día activo" : "días activos"} seguidos`);
    const week = byId("activity-week");
    week.replaceChildren();
    const dayFormat = new Intl.DateTimeFormat("es-ES", { weekday: "short" });
    summary.week.forEach(day => {
      const item = document.createElement("li");
      item.classList.toggle("is-active", day.answers > 0);
      item.classList.toggle("is-today", day.day === Study.day());
      if (day.day === Study.day()) item.setAttribute("aria-current", "date");
      const date = document.createElement("time");
      date.dateTime = day.day;
      date.textContent = dayFormat.format(new Date(`${day.day}T12:00:00`));
      const count = document.createElement("strong");
      count.textContent = String(day.answers);
      item.setAttribute("aria-label", `${day.day}: ${day.answers} preguntas distintas, ${day.correct} correctas`);
      item.append(date, count);
      week.append(item);
    });
    const weak = byId("weak-topics");
    weak.replaceChildren();
    const topics = [...summary.topics].sort((a, b) => Number(b.weak) - Number(a.weak) || b.due - a.due || (a.accuracy ?? 101) - (b.accuracy ?? 101) || a.tested - b.tested).slice(0, 3);
    topics.forEach(topic => {
      const item = document.createElement("li");
      const button = document.createElement("button");
      button.type = "button";
      button.className = "topic-recommendation";
      const title = document.createElement("strong");
      title.textContent = `${String(topic.topic).padStart(2, "0")} · ${TOPIC_NAMES[topic.topic]}`;
      const detail = document.createElement("span");
      detail.textContent = topic.tested ? `${Math.round(topic.accuracy)} % de acierto · ${topic.due} repasos pendientes →` : "Por descubrir · Empieza sin reloj →";
      button.append(title, detail);
      button.addEventListener("click", () => {
        selectTopics([topic.topic]);
        switchMode("practice");
        openGame();
      });
      item.append(button);
      weak.append(item);
    });
  }

  function updateCounts() {
    byId("question-total").textContent = String(QUESTION_BANK.length);
    byId("learned-total").textContent = String(progress.learned.length);
    byId("learned-count").textContent = String(progress.learned.length);
    byId("review-count").textContent = String(progress.review.length);
    byId("best-score").textContent = progress.bestScore.toLocaleString("es-ES");
    const count = filteredQuestions(state.temas).length;
    byId("selection-count").textContent = `${state.temas.length} ${state.temas.length === 1 ? "tema" : "temas"} · ${count} preguntas`;
    byId("play-now").disabled = count === 0;
    renderDashboard();
    if (byId("progress-dialog").open) renderProgress();
  }

  function stopTimer() {
    if (timer !== null) clearInterval(timer);
    timer = null;
  }

  function updateClockUI() {
    const round = state.quiz;
    if (!round || round.mode !== "kahoot") return;
    byId("timer-seconds").textContent = String(Math.ceil(round.remaining));
    byId("timer-progress").value = round.remaining;
    byId("timer-state").textContent = round.paused ? "en pausa" : "restantes";
    byId("pause-timer").textContent = round.paused ? "Continuar" : "Pausar";
    byId("pause-timer").setAttribute("aria-pressed", String(round.paused));
    byId("pause-timer").disabled = round.resolved;
  }

  function startTimer() {
    stopTimer();
    const round = state.quiz;
    if (!round || round.paused || round.resolved || round.finished || state.mode !== "kahoot" || state.view !== "game") return;
    deadline = performance.now() + round.remaining * 1000;
    timer = setInterval(() => {
      round.remaining = Math.max(0, (deadline - performance.now()) / 1000);
      updateClockUI();
      if (round.remaining === 0) resolveQuiz(null);
    }, 100);
  }

  function pauseKahoot() {
    const round = state.quiz;
    if (!round || round.mode !== "kahoot" || round.paused || round.resolved || round.finished) return;
    round.remaining = Math.max(0, (deadline - performance.now()) / 1000);
    if (round.remaining === 0) { resolveQuiz(null); return; }
    round.paused = true;
    stopTimer();
    updateClockUI();
    byId("kahoot-options").querySelectorAll("button").forEach(button => { button.disabled = true; });
  }

  function renderQuiz() {
    const round = state.quiz;
    byId("kahoot-play").hidden = !round || round.finished;
    byId("kahoot-result").hidden = !round || !round.finished;
    if (!round) { updateCounts(); return; }
    if (round.finished) { renderQuizResult(); return; }
    const question = round.deck[round.index];
    const exam = round.mode === "exam";
    const timed = round.mode === "kahoot";
    byId("timed-hud").hidden = !timed;
    byId("study-session-hud").hidden = timed;
    byId("session-kind").textContent = exam ? "SIMULACRO" : round.mode === "daily" ? "PLAN DIARIO" : "PRÁCTICA SIN RELOJ";
    const answered = round.selections.filter(value => value !== null).length;
    byId("session-state").textContent = exam ? `Pregunta ${round.index + 1} / ${round.deck.length} · ${answered} respondidas` : `Pregunta ${round.index + 1} / ${round.deck.length} · Piensa y comprende, sin reloj`;
    byId("kahoot-meta").textContent = questionMeta(question);
    byId("kahoot-position").textContent = `${round.index + 1} / ${round.deck.length}`;
    setFormattedText(byId("kahoot-question"), question.question);
    renderOptions(byId("kahoot-options"), question, exam ? round.selections[round.index] : round.selected, !exam && round.resolved, round.paused || round.confirming, resolveQuiz);
    byId("kahoot-feedback").hidden = exam || !round.resolved;
    byId("kahoot-options").hidden = !exam && round.resolved;
    byId("kahoot-next").hidden = exam || !round.resolved;
    byId("kahoot-next").firstChild.textContent = round.index === round.deck.length - 1 ? "Ver resultado " : "Siguiente pregunta ";
    byId("kahoot-score-label").textContent = exam ? "RESPONDIDAS" : timed ? "PUNTUACIÓN" : "ACIERTOS";
    byId("kahoot-score").textContent = (exam ? answered : timed ? round.score : round.correct).toLocaleString("es-ES");
    byId("kahoot-score-unit").textContent = timed ? "puntos" : `de ${round.deck.length}`;
    byId("kahoot-note").textContent = exam
      ? "Corrección al terminar. Acierto +1, error −1/3, en blanco 0. Este simulacro de práctica no fija el formato de una convocatoria."
      : timed ? "Cada acierto suma. Tu velocidad decide la bonificación."
        : "Los errores y las dudas vuelven antes. Acertar repasos en días distintos consolida lo aprendido; repetir hoy no adelanta el repaso.";
    byId("mark-doubt").hidden = exam || timed || !round.resolved || !round.results[round.index];
    byId("mark-doubt").disabled = Boolean(question.doubt);
    byId("mark-doubt").textContent = question.doubt ? "Guardada para repasar mañana" : "La acerté con dudas";
    byId("exam-controls").hidden = !exam || round.confirming;
    byId("exam-prev").disabled = round.index === 0;
    byId("exam-next").disabled = round.index === round.deck.length - 1;
    byId("exam-clear").disabled = round.selections[round.index] === null;
    byId("exam-submit-area").hidden = !exam || !round.confirming;
    if (round.confirming) byId("exam-submit-summary").textContent = `${answered} respondidas y ${round.deck.length - answered} en blanco. Al corregir se cerrarán tus respuestas. Las preguntas respondidas actualizarán tu progreso; las omitidas irán a repaso.`;
    updateClockUI();
    if (!exam && round.resolved) {
      const title = round.selected === null ? "Tiempo agotado. La repasaremos." : round.results[round.index]
        ? timed ? `Correcto. +${round.earned} puntos.` : question.doubt ? "Correcta, con dudas. Volverá mañana." : "Correcto. Comprueba por qué encaja."
        : "Esta pregunta volverá a tu repaso.";
      renderFeedback(byId("kahoot-feedback"), title, question, question.selectedText);
    } else if (timed) startTimer();
  }

  function startQuiz(questions) {
    stopTimer();
    state.reviewIndex = 0;
    const pool = state.mode === "daily" ? QUESTION_BANK : filteredQuestions(state.temas);
    const selected = questions || (state.mode === "practice" || state.mode === "daily"
      ? Study.plan(pool, progress.study, progress.review, new Date(), ROUND_LENGTH)
      : shuffle(pool).slice(0, state.mode === "exam" ? EXAM_LENGTH : ROUND_LENGTH));
    const deck = selected.map(question => ({ ...prepareQuestion(question), doubt: false, selectedText: null }));
    if (!deck.length) return;
    state.quiz = { mode: state.mode, deck, index: 0, score: 0, correct: 0, missed: [], results: Array(deck.length).fill(null), selections: Array(deck.length).fill(null), remaining: ROUND_SECONDS, paused: false, resolved: false, finished: false, confirming: false, selected: null, earned: 0 };
    renderQuiz();
    byId("kahoot-question").focus({ preventScroll: true });
  }

  function resolveQuiz(selected) {
    const round = state.quiz;
    if (!round || round.resolved || round.finished || round.paused || round.confirming || !QUIZ_MODES.includes(state.mode) || state.view !== "game") return;
    if (selected !== null && (!Number.isInteger(selected) || selected < 0 || selected > 3)) return;
    if (round.mode === "exam") {
      round.selections[round.index] = selected;
      renderQuiz();
      byId("kahoot-options").querySelectorAll("button")[selected]?.focus({ preventScroll: true });
      return;
    }
    if (round.mode === "kahoot") {
      round.remaining = Math.max(0, (deadline - performance.now()) / 1000);
      if (round.remaining === 0) selected = null;
    }
    round.resolved = true;
    round.selected = selected;
    stopTimer();
    const question = round.deck[round.index];
    const correct = selected !== null && Boolean(question.choices[selected]?.correct);
    round.results[round.index] = correct;
    question.selectedText = question.choices[selected]?.text || null;
    round.earned = round.mode === "kahoot" ? calculateScore(correct, round.remaining, ROUND_SECONDS) : 0;
    round.score += round.earned;
    if (correct) round.correct += 1;
    else round.missed.push(question);
    const answeredAt = new Date();
    saveProgress(saved => { Study.answer(saved.study, question.id, correct, answeredAt); });
    renderQuiz();
    byId("kahoot-next").focus({ preventScroll: true });
  }

  async function nextQuiz() {
    const round = state.quiz;
    if (!round?.resolved || round.finished) return;
    if (round.index === round.deck.length - 1) {
      round.finished = true;
      if (round.mode === "kahoot") await saveProgress(saved => { saved.bestScore = Math.max(saved.bestScore, round.score); });
      else await pendingSave;
      if (state.quiz !== round || !byId("game-dialog").open) return;
      renderQuiz();
      byId("result-title").focus({ preventScroll: true });
      return;
    }
    round.index += 1;
    round.remaining = ROUND_SECONDS;
    round.resolved = false;
    round.paused = false;
    round.selected = null;
    round.earned = 0;
    renderQuiz();
    byId("kahoot-question").focus({ preventScroll: true });
  }

  function renderQuizResult() {
    const round = state.quiz;
    const grade = Study.examScore(round.results);
    const timed = round.mode === "kahoot";
    const exam = round.mode === "exam";
    byId("result-title").textContent = exam ? "Simulacro corregido." : round.mode === "daily" ? "Tu plan, completado." : "Una sesión más. Un paso adelante.";
    byId("result-score").textContent = timed ? round.score.toLocaleString("es-ES") : exam ? grade.net.toLocaleString("es-ES", { maximumFractionDigits: 2 }) : String(round.correct);
    byId("result-score-unit").textContent = timed ? "puntos" : exam ? `puntos netos de ${round.deck.length}` : `aciertos de ${round.deck.length}`;
    byId("result-accuracy").textContent = `${grade.correct} de ${round.deck.length} correctas · ${exam ? `${grade.wrong} errores · ${grade.blank} en blanco · ` : ""}${Math.round(grade.correct / round.deck.length * 100)} % de acierto`;
    const summary = Study.summary(QUESTION_BANK, progress.study);
    byId("result-summary").textContent = `${summary.today.answers} preguntas distintas hoy · ${summary.consolidated} consolidadas. ${round.missed.length ? "Los errores, las dudas y las omitidas quedan para repasar. Puedes trabajarlas ahora; el siguiente repaso seguirá previsto para mañana." : "Vuelve cuando toque el siguiente repaso para comprobar que las recuerdas."}${exam ? " Puntuación de entrenamiento: aciertos − errores/3; no es una nota oficial." : ""}`;
    byId("practice-missed").hidden = round.missed.length === 0;
    byId("practice-missed").textContent = `Practicar ${round.missed.length} pendientes`;
    byId("result-review-area").hidden = round.missed.length === 0;
    const question = round.missed[state.reviewIndex];
    if (question) {
      setFormattedText(byId("result-review-question"), question.question);
      byId("result-review-meta").textContent = questionMeta(question);
      renderFeedback(byId("result-review"), question.doubt ? "Correcta con dudas: comprueba el razonamiento" : question.selectedText ? "Respuesta y explicación" : "Sin responder: respuesta y explicación", question, question.selectedText);
      byId("result-review-position").textContent = `${state.reviewIndex + 1} / ${round.missed.length} para repasar`;
      byId("review-prev").disabled = state.reviewIndex === 0;
      byId("review-next").disabled = state.reviewIndex === round.missed.length - 1;
    }
  }

  function moveExam(direction) {
    const round = state.quiz;
    if (!round || round.mode !== "exam" || round.finished || round.confirming) return;
    round.index = Math.max(0, Math.min(round.deck.length - 1, round.index + direction));
    renderQuiz();
    byId("kahoot-question").focus({ preventScroll: true });
  }

  async function finishExam() {
    const round = state.quiz;
    if (!round || round.mode !== "exam" || round.finished || !round.confirming) return;
    round.finished = true;
    round.results = round.deck.map((question, index) => {
      const selected = round.selections[index];
      question.selectedText = question.choices[selected]?.text || null;
      return selected === null ? null : Boolean(question.choices[selected].correct);
    });
    const grade = Study.examScore(round.results);
    round.correct = grade.correct;
    round.missed = round.deck.filter((question, index) => round.results[index] !== true);
    byId("exam-confirm").disabled = true;
    const answeredAt = new Date();
    await saveProgress(saved => {
      round.deck.forEach((question, index) => {
        if (round.results[index] === null) Study.flag(saved.study, question.id, answeredAt);
        else Study.answer(saved.study, question.id, round.results[index], answeredAt);
      });
      saved.study.exams.push({ day: Study.day(answeredAt), correct: grade.correct, wrong: grade.wrong, blank: grade.blank, total: round.deck.length, net: grade.net });
    });
    byId("exam-confirm").disabled = false;
    if (state.quiz !== round || !byId("game-dialog").open) return;
    renderQuiz();
    byId("result-title").focus({ preventScroll: true });
  }

  function renderTrivial() {
    const total = state.temas.reduce((sum, tema) => sum + progress.temas[tema], 0);
    const target = state.temas.length * TRIVIAL_TARGET;
    byId("trivial-progress").max = target;
    byId("trivial-progress").value = total;
    byId("trivial-progress-text").textContent = `${total} de ${target} aciertos · ${state.temas.length} ${state.temas.length === 1 ? "tema" : "temas"}`;
    byId("trivial-board-area").hidden = state.trivial !== null || total === target;
    byId("trivial-board").replaceChildren();
    const shortScreen = window.matchMedia("(max-height: 480px)").matches;
    const pageSize = shortScreen ? (window.matchMedia("(min-width: 600px)").matches ? 3 : 2) : window.matchMedia("(max-height: 600px)").matches ? 4 : 6;
    const pages = Math.ceil(state.temas.length / pageSize);
    state.boardPage = Math.min(state.boardPage, Math.max(0, pages - 1));
    state.temas.slice(state.boardPage * pageSize, state.boardPage * pageSize + pageSize).forEach(tema => {
      const count = progress.temas[tema];
      const button = document.createElement("button");
      button.type = "button";
      button.className = "category-tile";
      button.disabled = count >= TRIVIAL_TARGET;
      button.setAttribute("aria-label", `Tema ${tema}: ${TOPIC_NAMES[tema]}, ${count} de ${TRIVIAL_TARGET} aciertos`);
      const name = document.createElement("strong");
      name.textContent = `Tema ${String(tema).padStart(2, "0")}`;
      const title = document.createElement("span");
      title.textContent = TOPIC_NAMES[tema];
      const status = document.createElement("span");
      status.className = "tile-foot";
      status.textContent = `${count} / ${TRIVIAL_TARGET}${count >= TRIVIAL_TARGET ? " · Completado" : " · Jugar"}`;
      button.append(name, title, status);
      button.addEventListener("click", () => pickTrivial(tema));
      byId("trivial-board").append(button);
    });
    byId("board-position").textContent = `${state.boardPage + 1} / ${pages}`;
    byId("board-prev").disabled = state.boardPage === 0;
    byId("board-next").disabled = state.boardPage >= pages - 1;
    byId("trivial-complete").hidden = total !== target || state.trivial !== null;
    byId("trivial-play").hidden = state.trivial === null;
    if (!state.trivial) return;
    const { question, selected, resolved } = state.trivial;
    byId("trivial-meta").textContent = questionMeta(question);
    byId("trivial-position").textContent = `${progress.temas[question.tema]} / ${TRIVIAL_TARGET} aciertos`;
    setFormattedText(byId("trivial-question"), question.question);
    renderOptions(byId("trivial-options"), question, selected, resolved, false, resolveTrivial);
    byId("trivial-options").hidden = resolved;
    byId("trivial-feedback").hidden = !resolved;
    byId("trivial-next").hidden = !resolved;
    if (resolved) renderFeedback(byId("trivial-feedback"), question.choices[selected]?.correct ? "Correcto. Una pieza más cerca." : "No esta vez. Los errores no restan.", question);
  }

  function pickTrivial(tema) {
    if (state.trivial || !state.temas.includes(tema) || progress.temas[tema] >= TRIVIAL_TARGET || state.view !== "game") return;
    if (!trivialPools[tema]?.length) trivialPools[tema] = shuffle(filteredQuestions([tema]));
    state.trivial = { question: prepareQuestion(trivialPools[tema].pop()), selected: null, resolved: false };
    renderTrivial();
    byId("trivial-question").focus({ preventScroll: true });
  }

  async function resolveTrivial(selected) {
    const round = state.trivial;
    if (!round || round.resolved || state.mode !== "trivial" || state.view !== "game") return;
    round.resolved = true;
    round.selected = selected;
    const correct = Boolean(round.question.choices[selected]?.correct);
    const answeredAt = new Date();
    await saveProgress(saved => {
      if (correct) {
        const tema = round.question.tema;
        saved.temas[tema] = Math.min(TRIVIAL_TARGET, saved.temas[tema] + 1);
      }
      Study.answer(saved.study, round.question.id, correct, answeredAt);
    });
    if (state.trivial !== round || !byId("game-dialog").open) return;
    renderTrivial();
    byId("trivial-next").focus({ preventScroll: true });
  }

  function startFlashSession() {
    const allowed = state.scope === "all" ? null : new Set(progress[state.scope]);
    const deck = shuffle(filteredQuestions(state.temas).filter(question => !allowed || allowed.has(question.id)));
    state.flash = { deck, index: 0, flipped: false };
    renderFlash();
  }

  function renderFlash() {
    const session = state.flash;
    document.querySelectorAll("[data-scope]").forEach(button => {
      const active = button.dataset.scope === state.scope;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", String(active));
    });
    const question = session?.deck[session.index];
    byId("flash-session").hidden = !question;
    byId("flash-empty").hidden = Boolean(question);
    if (!question) {
      const completed = Boolean(session?.deck.length);
      byId("flash-empty-title").textContent = completed ? "Sesión completada." : "Todavía no hay tarjetas aquí.";
      byId("flash-empty-message").textContent = completed ? "Cada repaso cuenta. Puedes volver a recorrer estas tarjetas cuando quieras." : state.scope === "review" ? "Marca tarjetas como Repasar para encontrarlas aquí. Prueba también otra categoría." : state.scope === "learned" ? "Las tarjetas que marques como Aprendido aparecerán aquí." : "Prueba otra categoría para seguir estudiando.";
      byId("restart-flash").textContent = completed ? "Repetir sesión" : "Mostrar todas las tarjetas";
      return;
    }
    byId("flash-meta").textContent = questionMeta(question);
    byId("flash-position").textContent = `${session.index + 1} / ${session.deck.length}`;
    setFormattedText(byId("flash-front"), question.question);
    setFormattedText(byId("flash-answer"), question.options[question.answer]);
    setFormattedText(byId("flash-explanation"), question.explanation);
    syncFlashFace();
  }

  function syncFlashFace() {
    const session = state.flash;
    const question = session?.deck[session.index];
    if (!question) return;
    const flipped = session.flipped;
    byId("flash-card").classList.toggle("is-flipped", flipped);
    byId("flash-card").setAttribute("aria-pressed", String(flipped));
    byId("flash-card").setAttribute("aria-label", flipped ? `Respuesta: ${question.options[question.answer].replaceAll("`", "")}. ${question.explanation.replaceAll("`", "")}. Toca para volver a la pregunta.` : `Pregunta: ${question.question.replaceAll("`", "")}. Toca para mostrar la respuesta.`);
    byId("flash-front-face").setAttribute("aria-hidden", String(flipped));
    byId("flash-back-face").setAttribute("aria-hidden", String(!flipped));
    byId("mark-review").disabled = !flipped;
    byId("mark-learned").disabled = !flipped;
    byId("flash-guidance").textContent = flipped ? "¿Lo tenías claro? Decide cómo quieres volver a verlo." : "Primero intenta responder. Después gira la tarjeta.";
  }

  function nextFlash() {
    if (!state.flash?.deck[state.flash.index]) return;
    state.flash.index += 1;
    state.flash.flipped = false;
    renderFlash();
    byId(state.flash.deck[state.flash.index] ? "flash-card" : "restart-flash").focus({ preventScroll: true });
  }

  async function markFlash(bucket) {
    const session = state.flash;
    const question = session?.deck[session.index];
    if (!question || !session.flipped || session.saving) return;
    session.saving = true;
    byId("mark-learned").disabled = true;
    byId("mark-review").disabled = true;
    const markedAt = new Date();
    await saveProgress(saved => {
      saved.learned = saved.learned.filter(id => id !== question.id);
      saved.review = saved.review.filter(id => id !== question.id);
      saved[bucket].push(question.id);
      if (bucket === "review") Study.flag(saved.study, question.id, markedAt);
    });
    session.saving = false;
    if (state.flash === session && session.deck[session.index] === question && byId("game-dialog").open) nextFlash();
  }

  function setView(view) {
    state.view = view;
    document.body.classList.remove("view-home", "view-selection", "view-game");
    document.body.classList.add(`view-${view}`);
    byId("home-view").hidden = view !== "home";
    byId("selection-view").hidden = view !== "selection";
  }

  function switchMode(mode) {
    if (![...QUIZ_MODES, "trivial", "flashcards"].includes(mode)) return;
    state.mode = mode;
    const descriptions = {
      daily: "Diez preguntas de todo el anexo, priorizando tus repasos, errores y temas por reforzar. Sin reloj.",
      practice: "Hasta diez preguntas adaptadas a tu progreso. Sin reloj, con explicación y repaso de errores y dudas.",
      exam: "Hasta 40 preguntas de entrenamiento · Sin reloj · Puedes cambiar respuestas o dejarlas en blanco. Corrección al terminar: aciertos − errores/3. Las respuestas solo se guardan al corregir. Consulta las bases de tu convocatoria para el formato oficial.",
      kahoot: "Hasta diez preguntas · 30 segundos por pregunta · Acierto y velocidad." ,
      trivial: "Tres aciertos por tema. Completa los temas que elijas.",
      flashcards: "Gira, comprende y decide: Aprendido o Repasar."
    };
    byId("mode-description").textContent = descriptions[mode];
    const titles = { practice: "Práctica sin reloj", daily: "Plan diario", exam: "Simulacro", kahoot: "Kahoot", trivial: "Trivial", flashcards: "Flashcards" };
    byId("game-title").textContent = titles[mode];
    byId("kahoot-view").setAttribute("aria-label", titles[mode]);
    byId("play-now").firstChild.textContent = mode === "exam" ? "Empezar simulacro " : "Empezar a estudiar ";
    document.querySelectorAll("[data-mode]").forEach(button => {
      const active = button.dataset.mode === mode;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", String(active));
    });
    byId("kahoot-view").hidden = !QUIZ_MODES.includes(mode);
    ["trivial", "flashcards"].forEach(name => { byId(`${name}-view`).hidden = name !== mode; });
  }

  function selectTopics(temas) {
    byId("topic-list").querySelectorAll("input").forEach(input => { input.checked = temas.includes(Number(input.value)); });
    updateTopicSelection();
  }

  function updateTopicSelection() {
    state.temas = Array.from(byId("topic-list").querySelectorAll("input:checked"), input => Number(input.value));
    updateCounts();
  }

  function renderTopics() {
    Object.entries(TOPIC_NAMES).forEach(([number, title]) => {
      const label = document.createElement("label");
      label.className = "topic-choice";
      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.value = number;
      checkbox.checked = true;
      checkbox.addEventListener("change", updateTopicSelection);
      const text = document.createElement("span");
      const name = document.createElement("strong");
      name.textContent = `Tema ${number.padStart(2, "0")}`;
      const description = document.createElement("span");
      description.textContent = title;
      text.append(name, description);
      label.append(checkbox, text);
      byId("topic-list").append(label);
    });
  }

  function openGame(questions) {
    if (!filteredQuestions(state.temas).length) return;
    state.quiz = null;
    state.trivial = null;
    state.flash = null;
    state.scope = "all";
    state.boardPage = 0;
    setView("game");
    // El aviso debe estar dentro del diálogo para seguir visible y accesible mientras estudias.
    byId("game-dialog").append(byId("storage-notice"));
    byId("game-dialog").showModal();
    if (QUIZ_MODES.includes(state.mode)) startQuiz(questions);
    else if (state.mode === "trivial") { renderTrivial(); byId("trivial-board").querySelector("button:not(:disabled)")?.focus(); }
    else { startFlashSession(); byId("flash-card").focus(); }
  }

  byId("go-play").addEventListener("click", () => { setView("selection"); byId("selection-title").focus(); });
  byId("start-daily").addEventListener("click", () => {
    selectTopics(Object.keys(TOPIC_NAMES).map(Number));
    switchMode("daily");
    openGame();
  });
  byId("go-home").addEventListener("click", () => { setView("home"); byId("go-play").focus(); });
  byId("play-now").addEventListener("click", () => openGame());
  byId("show-progress").addEventListener("click", () => {
    renderProgress();
    byId("progress-dialog").showModal();
    byId("progress-dialog").scrollTop = 0;
  });
  byId("close-progress").addEventListener("click", () => byId("progress-dialog").close());
  byId("progress-dialog").addEventListener("close", () => byId("show-progress").focus());
  byId("close-game").addEventListener("click", () => byId("game-dialog").close());
  byId("game-dialog").addEventListener("close", () => {
    pauseKahoot();
    stopTimer();
    document.body.append(byId("storage-notice"));
    if (state.mode === "daily") switchMode("practice");
    setView("selection");
    byId("play-now").focus();
  });
  document.querySelectorAll("[data-mode]").forEach(button => button.addEventListener("click", () => switchMode(button.dataset.mode)));
  ["select-all", "select-none"].forEach(id => byId(id).addEventListener("click", () => {
    byId("topic-list").querySelectorAll("input").forEach(input => { input.checked = id === "select-all"; });
    updateTopicSelection();
  }));
  byId("restart-kahoot").addEventListener("click", () => startQuiz());
  byId("kahoot-next").addEventListener("click", nextQuiz);
  byId("mark-doubt").addEventListener("click", () => {
    const round = state.quiz;
    const question = round?.deck[round.index];
    if (!round?.resolved || !["practice", "daily"].includes(round.mode) || !round.results[round.index] || question.doubt) return;
    question.doubt = true;
    if (!round.missed.includes(question)) round.missed.push(question);
    const markedAt = new Date();
    saveProgress(saved => { Study.flag(saved.study, question.id, markedAt); });
    renderQuiz();
    byId("kahoot-next").focus({ preventScroll: true });
  });
  byId("practice-missed").addEventListener("click", () => {
    const questions = state.quiz?.missed;
    if (!questions?.length) return;
    switchMode("practice");
    startQuiz(questions);
  });
  byId("exam-prev").addEventListener("click", () => moveExam(-1));
  byId("exam-next").addEventListener("click", () => moveExam(1));
  byId("exam-clear").addEventListener("click", () => resolveQuiz(null));
  byId("exam-finish").addEventListener("click", () => {
    const round = state.quiz;
    if (!round || round.mode !== "exam" || round.finished) return;
    round.confirming = true;
    renderQuiz();
    byId("exam-confirm").focus({ preventScroll: true });
  });
  byId("exam-cancel").addEventListener("click", () => {
    if (!state.quiz || state.quiz.finished) return;
    state.quiz.confirming = false;
    renderQuiz();
    byId("kahoot-question").focus({ preventScroll: true });
  });
  byId("exam-confirm").addEventListener("click", finishExam);
  ["review-prev", "review-next"].forEach(id => byId(id).addEventListener("click", () => {
    state.reviewIndex = Math.max(0, Math.min(state.quiz.missed.length - 1, state.reviewIndex + (id === "review-next" ? 1 : -1)));
    renderQuizResult();
  }));
  byId("pause-timer").addEventListener("click", () => {
    const round = state.quiz;
    if (!round || round.resolved || round.finished) return;
    if (!round.paused) pauseKahoot();
    else { round.paused = false; renderQuiz(); }
  });
  ["board-prev", "board-next"].forEach(id => byId(id).addEventListener("click", () => {
    state.boardPage += id === "board-next" ? 1 : -1;
    renderTrivial();
  }));
  byId("trivial-next").addEventListener("click", () => {
    if (!state.trivial?.resolved) return;
    state.trivial = null;
    renderTrivial();
    (byId("trivial-board").querySelector("button:not(:disabled)") || byId("close-game")).focus({ preventScroll: true });
  });
  byId("reset-trivial").addEventListener("click", async () => {
    const temas = state.temas.slice();
    temas.forEach(tema => { delete trivialPools[tema]; });
    state.trivial = null;
    await saveProgress(saved => { temas.forEach(tema => { saved.temas[tema] = 0; }); });
    if (state.mode !== "trivial" || !byId("game-dialog").open) return;
    renderTrivial();
    byId("trivial-board").querySelector("button").focus();
  });
  document.querySelectorAll("[data-scope]").forEach(button => button.addEventListener("click", () => {
    state.scope = button.dataset.scope;
    startFlashSession();
  }));
  byId("flash-card").addEventListener("click", () => {
    if (!state.flash?.deck[state.flash.index]) return;
    state.flash.flipped = !state.flash.flipped;
    syncFlashFace();
  });
  byId("mark-learned").addEventListener("click", () => markFlash("learned"));
  byId("mark-review").addEventListener("click", () => markFlash("review"));
  byId("skip-flash").addEventListener("click", nextFlash);
  byId("restart-flash").addEventListener("click", () => {
    if (!state.flash?.deck.length) state.scope = "all";
    startFlashSession();
  });
  document.addEventListener("visibilitychange", () => {
    if (document.hidden && state.mode === "kahoot") pauseKahoot();
    if (!document.hidden) updateCounts();
  });
  document.addEventListener("keydown", event => {
    if (state.view !== "game" || event.ctrlKey || event.altKey || event.metaKey || /^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName) || event.target.isContentEditable) return;
    if (!/^[1-4]$/.test(event.key)) return;
    const container = QUIZ_MODES.includes(state.mode) ? byId("kahoot-options") : state.mode === "trivial" ? byId("trivial-options") : null;
    const button = container?.querySelectorAll("button")[Number(event.key) - 1];
    if (button && !button.disabled) { event.preventDefault(); button.click(); }
  });
  window.addEventListener("resize", () => { if (state.view === "game" && state.mode === "trivial") renderTrivial(); });
  window.addEventListener("pagehide", () => { pauseKahoot(); stopTimer(); });
  window.addEventListener("storage", event => {
    if (event.key !== STORAGE_KEY && event.key !== null) return;
    try {
      const latest = readProgress();
      unsavedChanges.forEach(change => change(latest));
      progress = normalizeProgress(latest);
      if (!unsavedChanges.length) {
        storageAvailable = true;
        byId("storage-notice").hidden = true;
      }
    }
    catch { showStorageNotice(); }
    updateCounts();
    if (state.view === "game" && state.mode === "trivial") renderTrivial();
  });
  renderTopics();
  updateCounts();
  switchMode("practice");
  setView("home");
});

window.addEventListener("load", () => {
  if (!window.isSecureContext || !/^https?:$/.test(location.protocol) || !("serviceWorker" in navigator)) return;
  navigator.serviceWorker.register("./sw.js").catch(error => {
    console.warn("No se pudo activar el modo offline:", error);
  });
});
